CREATE TABLE `alerts` (
  `alert_id` int NOT NULL AUTO_INCREMENT,
  `transaction_id` varchar(50) NOT NULL,
  `merchant_id` varchar(50) NOT NULL,
  `risk_score` int DEFAULT NULL,
  `base_rule_score` int NOT NULL DEFAULT '0',
  `mcc_risk_points` int NOT NULL DEFAULT '0',
  `raw_risk_score` int NOT NULL DEFAULT '0',
  `displayed_risk_score` int NOT NULL DEFAULT '0',
  `priority_multiplier` decimal(6,2) NOT NULL DEFAULT '1.00',
  `priority_score` int NOT NULL DEFAULT '0',
  `risk_level` varchar(20) DEFAULT NULL,
  `triggered_rules` json DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'open',
  `priority` varchar(20) DEFAULT NULL,
  `message` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` datetime DEFAULT NULL,
  `reviewed_by` int DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `assigned_to` int DEFAULT NULL,
  `escalated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`alert_id`),
  KEY `idx_alerts_transaction` (`transaction_id`),
  KEY `idx_alerts_merchant` (`merchant_id`),
  KEY `idx_alerts_reviewed_by` (`reviewed_by`),
  KEY `idx_alerts_assigned_to` (`assigned_to`),
  KEY `idx_alerts_status_created` (`status`,`created_at`),
  KEY `idx_alerts_risk_priority` (`risk_level`,`priority`),
  CONSTRAINT `fk_alerts_assigned_to` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_alerts_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`merchant_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_alerts_reviewed_by` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_alerts_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `transactions` (`transaction_id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
