CREATE TABLE `compliance_rules` (
  `rule_id` int NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(100) NOT NULL,
  `rule_type` varchar(50) DEFAULT NULL,
  `description` text,
  `threshold_value` decimal(12,2) DEFAULT NULL,
  `threshold_count` int DEFAULT NULL,
  `time_window_minutes` int DEFAULT NULL,
  `time_window_seconds` int DEFAULT NULL,
  `points` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`rule_id`),
  UNIQUE KEY `uq_compliance_rules_rule_type` (`rule_type`),
  KEY `idx_compliance_rules_active` (`is_active`),
  KEY `idx_compliance_rules_created_by` (`created_by`),
  KEY `idx_compliance_rules_updated_by` (`updated_by`),
  CONSTRAINT `fk_compliance_rules_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_compliance_rules_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
