INSERT INTO `compliance_rules` VALUES (1,'Significant amount compared to merchant average','large_transaction','Flags transactions greater than three times the merchant average amount.',3.00,NULL,NULL,NULL,30,1,1,2,'2026-07-03 08:31:01','2026-07-15 03:23:19'),(2,'High transaction velocity','transaction_velocity','Flags successful or completed transaction velocity by payment identifier. Failed, declined and cancelled transactions are captured only as intake statuses and are not monitored.',NULL,10,1,30,25,1,1,2,'2026-07-03 08:31:01','2026-07-22 13:35:58'),(3,'Transaction outside merchant operating hours','outside_operating_hours','Flags transactions made outside the merchant operating_hours_start and operating_hours_end values. The rule is skipped when operating hours are missing.',NULL,NULL,NULL,NULL,10,1,1,2,'2026-07-03 08:31:01','2026-07-21 15:56:28'),(4,'High-risk customer profile','customer_risk','Adds risk points when the customer profile is marked high risk.',NULL,NULL,NULL,NULL,25,0,1,2,'2026-07-03 08:31:01','2026-07-23 09:27:58'),(5,'High-risk country/jurisdiction','jurisdiction','Flags transactions from configured high-risk countries or jurisdictions.',NULL,NULL,NULL,NULL,30,0,1,NULL,'2026-07-03 08:31:01','2026-07-23 09:27:58'),(6,'Missing or insufficient transaction information','data_quality','Flags transactions missing useful identifying references such as masked card, masked payment reference, terminal ID, or gateway reference.',NULL,NULL,NULL,NULL,20,1,1,2,'2026-07-03 08:31:01','2026-07-21 14:28:24'),(7,'Online transaction with missing/invalid IP','ip_validation','Flags online transactions where IP address is missing or invalid.',NULL,NULL,NULL,NULL,10,1,1,2,'2026-07-03 08:31:01','2026-07-21 16:01:58'),(8,'Large cross-border transfer amount if country is not Singapore','cross_border','Flags SGD transactions above 1500 when the transaction country is not Singapore.',1500.00,NULL,NULL,NULL,25,0,1,NULL,'2026-07-03 08:31:01','2026-07-23 09:27:58'),(9,'Merchant MCC/base industry risk score','merchant_category_risk','Adds base risk using merchant MCC or business category: F&B +5, retail +10, electronics +15, travel/tourism/hotel +20, money service/remittance/financial/gambling +30.',NULL,NULL,NULL,NULL,30,1,1,2,'2026-07-03 19:52:32','2026-07-15 03:23:19'),(10,'Repeated small transactions','repeated_small_transactions','Repeated small transactions detected: 5 transactions below SGD 10 within 5 minutes.',10.00,5,5,300,20,1,1,2,'2026-07-03 19:52:33','2026-07-21 15:54:54'),(11,'Frequent large amount transactions','frequent_large_transactions','Frequent large amount transactions detected within 30 minutes.',3.00,3,30,1800,30,1,1,2,'2026-07-03 19:52:33','2026-07-21 15:51:53'),(12,'Repeated failed or declined payment attempts','failed_attempt_velocity','Inactive future enhancement. Failed, declined and cancelled transactions do not enter compliance monitoring under the current project scope.',NULL,3,10,600,25,0,1,2,'2026-07-03 19:52:33','2026-07-22 13:35:58'),(13,'Failed attempts followed by success','failure_then_success','Inactive future enhancement. Failed-payment sequences are excluded from active merchant-focused monitoring under the current project scope.',NULL,3,10,600,30,0,1,1,'2026-07-06 02:35:20','2026-07-22 13:35:58'),(14,'Possible duplicate or replayed payment','duplicate_payment_identifier','Flags a new transaction that repeats the same merchant, amount, and payment identifier within a short time window.',NULL,1,1,60,25,1,1,1,'2026-07-06 02:35:20','2026-07-15 03:23:19'),(15,'High-risk jurisdiction','high_risk_jurisdiction','Checks the transaction country against the high_risk_jurisdictions table. Activate only after an approved list is configured.',NULL,NULL,NULL,NULL,25,0,1,1,'2026-07-06 02:35:20','2026-07-23 09:27:58'),(16,'IP country mismatch','ip_country_mismatch','Flags online transactions when the submitted country differs from the recorded IP-derived country.',NULL,NULL,NULL,NULL,20,0,1,1,'2026-07-06 02:35:20','2026-07-06 02:35:20'),(17,'Daily transaction count spike','daily_transaction_count_spike','Flags daily transaction counts above merchant history, MCC defaults, or configured defaults.',NULL,50,NULL,NULL,15,1,1,1,'2026-07-15 03:23:20','2026-07-15 03:23:20'),(18,'Daily transaction value spike','daily_transaction_value_spike','Flags daily transaction value above merchant history, MCC defaults, or configured defaults.',25000.00,NULL,NULL,NULL,20,1,1,1,'2026-07-15 03:23:20','2026-07-15 03:23:20'),(19,'Merchant average deviation','merchant_average_deviation','Compares the transaction amount with merchant_average_amount using the configured multiplier; shares the amount_anomaly scoring group.',5.00,NULL,NULL,NULL,25,1,1,1,'2026-07-15 03:23:20','2026-07-15 03:23:20'),(20,'Repeated identical amounts','repeated_identical_amounts','Flags repeated exact or near-identical transaction amounts for the same merchant within 5 minutes, even when payment identifiers differ.',NULL,4,5,300,15,1,1,1,'2026-07-15 03:23:20','2026-07-15 03:23:20'),(21,'Merchant MCC or industry risk','merchant_profile','Adds configured merchant profile risk points from the merchant_category_risk database table.',NULL,NULL,NULL,NULL,0,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(22,'Significant amount compared to merchant average','amount_multiplier','Flags transactions above a configurable multiple of the trusted merchant average amount.',3.00,NULL,NULL,NULL,25,0,1,2,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(23,'High transaction velocity','velocity','Flags successful or completed transaction velocity by payment identifier. Failed, declined and cancelled transactions are captured only as intake statuses and are not monitored.',NULL,6,1,60,25,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(24,'Repeated small transactions','velocity_small_amount','Flags repeated small-value transactions using the same payment identifier.',10.00,5,5,300,20,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(25,'Frequent unusually large transactions','large_amount_frequency','Flags repeated transactions above a configurable multiple of the merchant average.',3.00,3,30,1800,30,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(26,'Possible duplicate successful transaction','duplicate_transaction','Flags a successful transaction that repeats merchant, amount, currency, and payment identifier within a short window.',NULL,1,1,60,25,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58'),(27,'Transaction outside merchant operating hours','time','Applies only to face-to-face transactions for merchants with a physical location and recorded operating hours.',NULL,NULL,NULL,NULL,10,0,1,1,'2026-07-15 04:31:43','2026-07-23 09:27:58');
