INSERT INTO `str_reports` VALUES (3,13,1,NULL,'STR-2026-1784544276586','During routine transaction monitoring, the system detected unusual activity involving Chan Chinatown Hawker Stall.\r\n\r\nA transaction of SGD 9,850.00 was received through a mobile banking transfer. The value was significantly higher than the merchant\'s normal transaction pattern and was inconsistent with the expected activity of a small food and beverage business.\r\n\r\nThe funds originated from multiple third parties with no clear relationship to the merchant. Shortly after receipt, the funds were transferred to another corporate beneficiary. The activity showed possible rapid movement of funds and an unclear economic purpose.\r\n\r\nThe monitoring system identified an unusually large transaction, activity inconsistent with the merchant profile, possible structuring, and an unexplained third-party transfer.\r\n\r\nBased on the available information, the transaction may involve money laundering, fraud, or another financial crime. The case is therefore recommended for escalation and filing of a Suspicious Transaction Report.','feedback_required','2026-07-20 10:44:36','2026-07-22 11:24:00',NULL,NULL,'missing information',1,'2026-07-22 11:24:00',NULL),(4,16,1,NULL,'STR-2026-1784546951987','During routine transaction monitoring, the system detected unusual activity involving Chan Chinatown Hawker Stall.\r\n\r\nA transaction of SGD 9,850.00 was received through a mobile banking transfer. The value was significantly higher than the merchant\'s normal transaction pattern and was inconsistent with the expected activity of a small food and beverage business.\r\n\r\nThe funds originated from multiple third parties with no clear relationship to the merchant. Shortly after receipt, the funds were transferred to another corporate beneficiary. The activity showed possible rapid movement of funds and an unclear economic purpose.\r\n\r\nThe monitoring system identified an unusually large transaction, activi