--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `transaction_id` varchar(50) NOT NULL,
  `merchant_id` varchar(50) NOT NULL,
  `masked_payment_ref` varchar(100) DEFAULT NULL,
  `card_bin` varchar(10) DEFAULT NULL,
  `masked_card_number` varchar(30) DEFAULT NULL,
  `card_presence` varchar(20) DEFAULT NULL,
  `terminal_id` varchar(50) DEFAULT NULL,
  `payment_gateway_ref` varchar(100) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `transaction_type` varchar(50) DEFAULT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` varchar(10) NOT NULL DEFAULT 'SGD',
  `ip_address` varchar(45) DEFAULT NULL,
  `country` varchar(50) NOT NULL DEFAULT 'Singapore',
  `ip_country` varchar(50) DEFAULT NULL,
  `customer_risk_profile` varchar(20) DEFAULT NULL,
  `txn_time` datetime DEFAULT NULL,
  `transaction_status` varchar(30) DEFAULT NULL,
  `base_rule_score` int NOT NULL DEFAULT '0',
  `mcc_risk_points` int NOT NULL DEFAULT '0',
  `raw_risk_score` int NOT NULL DEFAULT '0',
  `displayed_risk_score` int NOT NULL DEFAULT '0',
  `priority_multiplier` decimal(6,2) NOT NULL DEFAULT '1.00',
  `priority_score` int NOT NULL DEFAULT '0',
  `risk_score` int NOT NULL DEFAULT '0',
  `risk_level` varchar(20) DEFAULT NULL,
  `triggered_rules` json DEFAULT NULL,
  `processing_status` varchar(50) DEFAULT NULL,
  `source_type` varchar(30) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`transaction_id`),
  KEY `idx_transactions_merchant` (`merchant_id`),
  KEY `idx_transactions_terminal` (`terminal_id`),
  KEY `idx_transactions_time` (`txn_time`),
  KEY `idx_transactions_risk` (`risk_level`,`risk_score`),
  KEY `idx_transactions_processing` (`processing_status`),
  CONSTRAINT `fk_transactions_merchant` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`merchant_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_transactions_terminal` FOREIGN KEY (`terminal_id`) REFERENCES `terminals` (`terminal_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

